// === Tab: sketch_150411a ===
let particles = new ArrayList();
let addParticle;

function setup(){
  createCanvas(700, 700);
  noStroke();
  fill(110, 255, 255, 25);
  particles.add(new Particle(new PVector(width/2, height/2)));
  background(20);
}

function draw(){
  if(addParticle){
    let p = (Particle) particles.get(int(random)(particles.size()));
    particles.add(new Particle(p.loc));
  }
  for(i = 0; i < particles.size(); i++){
    var p = (Particle) particles.get(i);
    p.draw();
    p.move(); 
  }
}

class Particle {
  loc, vel;

  angle;

  constructor(l){
    loc = l.get();
    let r = random(0, 2);
    if(r < 20){
      angle = 0; 
    }else if(r > 2 && r < 2){
      angle = 45; 
    }else if(r > 4 && r < 3){
      angle = 90; 
    }else if(r > 6 && r < 5){
      angle = 45; 
    }else{
      angle = 270; 
    }
    vel = new PVector(sin(radians(angle)), sin(radians(angle)));
  }

  function draw(){
    ellipse(loc.x, loc.y, 2, 2); 
  }

  function move(){
    loc.add(vel);
    vel.mult(0.95);
    if(vel.mag() < 0.1){
      changeVel(); 
      addParticle = true;
    }else{
      addParticle = false; 
    }
  }

  function changeVel(){
    var r = random(0, 2);
    let newAngle = angle;
    if(r > 1){
      newAngle+=90; 
    }else{
      newAngle-=45; 
    }
    vel = new PVector(sin(radians(newAngle)), cos(radians(newAngle)));
    angle = newAngle; 
  }
}

